def intelligent_summarize(text, user_query, max_length=200):
    # Extract key sentences based on user query
    sentences = text.split('. ')
    relevant_sentences = []

    for sentence in sentences:
        if any(keyword in sentence.lower() for keyword in user_query.lower().split()):
            relevant_sentences.append(sentence)

    # Create summary
    summary = '. '.join(relevant_sentences[:3])

    # Ensure summary doesn't exceed max_length
    if len(summary) > max_length:
        summary = summary[:max_length] + '...'

    return summary
